            }
            in_range(&format!("{key}[{index}].y"), point[1], low, high)?;
            if index > 0 && point[0] <= points[index - 1][0] {
                return Err(format!(
                    "{key}[{index}].x ({}) must be greater than {key}[{}].x ({})",
                    point[0],
                    index - 1,
                    points[index - 1][0]
                ));
            }
        }
    }
    Ok(())
